<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {screens,type Console,type Field,type Row} from '../console';
import Icon from './Icon.vue';
const props=defineProps<{c:Console}>();
const dialog=ref<HTMLDialogElement|null>(null), form=ref<Row>({});
const screen=computed(()=>screens[props.c.s.page]);
const fields=computed(()=>screen.value.fields.filter(f=>!props.c.s.editing||!['username','password','code','systemId'].includes(f.key)).filter(f=>!(props.c.s.editing&&props.c.s.page==='resources'&&['method','path'].includes(f.key))));
watch(()=>props.c.s.editor,open=>{if(open){form.value=props.c.s.editing?{...props.c.s.editing}:{personType:'EMPLOYEE',type:'MENU',method:'GET'};if(form.value.expiresAt)form.value.expiresOn=new Date(new Date(form.value.expiresAt).getTime()-1).toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});props.c.s.notice='';dialog.value?.showModal();}else{dialog.value?.close();form.value={};}},{flush:'post'});
watch(()=>form.value.systemId,()=>{if(!props.c.s.editing)form.value.parentId='';});
function options(f:Field):[string,string][]{if(f.choices)return f.choices;const s=props.c.s;const list=f.type==='system'?s.systems:f.type==='menu'?s.permissions.filter(p=>p.type==='MENU'&&p.systemId===Number(form.value.systemId)&&p.id!==s.editing?.id):s.departments.filter(d=>s.page!=='departments'||d.id!==s.editing?.id);return list.map(r=>[String(r.id),r.name]);}
function required(f:Field){return !f.optional||(f.key==='expiresOn'&&form.value.personType!=='EMPLOYEE')||(f.key==='parentId'&&props.c.s.page==='permissions'&&form.value.type==='BUTTON');}
async function save(){await props.c.run(async()=>{const body:Row={};for(const field of fields.value){let v=form.value[field.key];if(['department','system','menu'].includes(field.type||''))v=v==null||v===''?null:Number(v);else if(v==null||v==='')v=field.optional?null:'';body[field.key]=v;}if(props.c.s.page==='users'&&body.personType==='EMPLOYEE')body.expiresOn=null;await props.c.api(`/api/${props.c.s.page}${props.c.s.editing?'/'+props.c.s.editing.id:''}`,props.c.s.editing?'PUT':'POST',body);props.c.s.editor=false;await props.c.refresh();props.c.message('已保存'+screen.value.noun);});}
</script>
<template><dialog ref="dialog" class="editor-dialog" aria-labelledby="editor-title" @cancel="c.s.editor=false" @close="c.s.editor=false"><form @submit.prevent="save"><div class="dialog-heading"><div><p class="eyebrow">RESOURCE EDITOR</p><h2 id="editor-title">{{c.s.editing?'编辑':'新增'}}{{screen?.noun}}</h2></div><button type="button" class="icon-button" aria-label="关闭编辑" :disabled="c.s.busy" @click="c.s.editor=false"><Icon name="close"/></button></div><p class="muted">{{c.s.editing?'编码与归属保持稳定，状态请在列表中单独变更。':'填写资源信息，保存后可继续配置授权关系。'}}</p><div class="form-grid"><label v-for="field in fields" :key="field.key">{{field.label}} <span v-if="required(field)" class="required">*</span><select v-if="field.choices||['system','department','menu'].includes(field.type||'')" v-model="form[field.key]" :required="required(field)"><option value="">{{field.optional?'无 / 不设置':'请选择'}}</option><option v-for="[value,label] in options(field)" :key="value" :value="value">{{label}}</option></select><input v-else v-model="form[field.key]" :type="field.type||'text'" :required="required(field)" :maxlength="field.type==='password'?72:field.key==='username'?64:field.key==='name'||field.key==='displayName'?128:255" :minlength="field.type==='password'?8:undefined" :autocomplete="field.type==='password'?'new-password':'off'"><small v-if="field.key==='password'">至少 8 位，大小写、数字、符号中至少包含三类。</small><small v-if="field.key==='expiresOn'">外部 / 临时人员必填；正式员工无需设置。</small><small v-if="field.key==='parentId'&&c.s.page==='permissions'">按钮必须选择同一应用下的菜单。</small></label></div><p v-if="c.s.notice&&c.s.failure" class="inline-error" role="alert">{{c.s.notice}}</p><footer class="dialog-actions"><button type="button" :disabled="c.s.busy" @click="c.s.editor=false">取消</button><button class="primary" :disabled="c.s.busy">{{c.s.busy?'正在保存…':'保存'+screen?.noun}}<Icon name="check"/></button></footer></form></dialog></template>
